"use strict";
(() => {
  const OBJECTS = [
    ["counters", "●"],
    ["stars", "★"],
    ["buttons", "●"],
    ["shells", "🐚"],
    ["hearts", "♥"]
  ];
  const DAYS = ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday"];
  const MATERIAL_LABELS = ["Counter card", "Button card", "Shell card", "Toy card", "Picture card"];
  const PATTERNS = [["🔴","🔵"],["★","○"],["👏","👣","👣"],["▲","■","●"],["A","B","B"]];

  const id = (code, bank, i) => `${code.toLowerCase()}-${bank[0]}-${String(i + 1).padStart(3, "0")}`;
  const base = (c, type, skill, question, extra = {}) => ({
    id: id(c.code, c.bank, c.i),
    curriculumCode: c.code,
    bank: c.bank,
    skill,
    question,
    explanation: extra.explanation || "Check the model and count carefully.",
    printable: true,
    type,
    ...Object.fromEntries(Object.entries(extra).filter(([key]) => key !== "explanation"))
  });
  const cleanAnswers = (correct, distractors, i) => {
    const values = [];
    [correct, ...distractors].map(String).forEach((value) => {
      if (!values.includes(value)) values.push(value);
    });
    if (values.length < 3 && /^-?\d+$/.test(String(correct))) {
      const n = Number(correct);
      [Math.max(0, n - 1), n + 1, n + 2].map(String).forEach((value) => {
        if (!values.includes(value) && values.length < 3) values.push(value);
      });
    }
    if (values.length < 3) {
      ["It cannot be determined", "No change"].forEach((value) => {
        if (!values.includes(value) && values.length < 3) values.push(value);
      });
    }
    const trimmed = values.slice(0, 4);
    const shift = i % trimmed.length;
    const answers = [...trimmed.slice(shift), ...trimmed.slice(0, shift)];
    return { answers, correct: answers.indexOf(String(correct)) };
  };
